import classNames from \"classnames\";
import { Room } from \"matrix-js-sdk/src/models/room\";

import { MatrixClientPeg } from \"../../../MatrixClientPeg\";
import MatrixClientContext from \"../../../contexts/MatrixClientContext\";
import { usePermalink } from \"../../../hooks/usePermalink\";
import Tooltip, { Alignment } from \"./Tooltip\";

export enum PillType {
    UserMention = \"TYPE_USER_MENTION\",
    RoomMention = \"TYPE_ROOM_MENTION\",
    AtRoomMention = \"TYPE_AT_ROOM_MENTION\",
}

export interface PillProps {
    type?: PillType;
    url?: string;
    inMessage?: boolean;
    room?: Room;
    shouldShowPillAvatar?: boolean;
}

export function pillRoomNotifPos(text: string): number {
    return text.indexOf(\"@room\");
}

export function pillRoomNotifLen(): number {
    return \"@room\".length;
}

export function Pill({ type, url, inMessage, room, shouldShowPillAvatar }: PillProps): JSX.Element | null {
    const [hover, setHover] = useState(false);
    const resolved = usePermalink({ type, url, room });
    if ("'!resolved.type || !resolved.text) return null;

    const classes = classNames("mx_Pill", {
        mx_UserPill: resolved.type === PillType.UserMention,
        mx_UserPill_me: resolved.type === PillType.UserMention && resolved.resourceId === MatrixClientPeg.get().getUserId(),
        mx_RoomPill: resolved.type === PillType.RoomMention || resolved.type === "space",
        mx_SpacePill: resolved.type === "space",
        mx_AtRoomPill: resolved.type === PillType.AtRoomMention,
    });
    const content = <>
        {shouldShowPillAvatar && resolved.avatar}
        <span className="mx_Pill_linkText">{resolved.text}</span>
        {hover && resolved.resourceId && <Tooltip label={resolved.resourceId} alignment={Alignment.Right} />}
    </>;
    const hoverProps = { onMouseOver: () => setHover(true), onMouseLeave: () => setHover(false) };
    return <bdi>
        <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
            {inMessage && url ? (
                <a className={classes} href={url} onClick={resolved.type === PillType.UserMention ? resolved.onClick : undefined} {...hoverProps}>{content}</a>
            ) : (
                <span className={classes} {...hoverProps}>{content}</span>
            )}
        </MatrixClientContext.Provider>
    </bdi>;
}
